import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Skills & Progression","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/progression.md","filePath":"en/guide/characters/progression.md"}'),s={name:"en/guide/characters/progression.md"};function o(n,e,l,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="skills-progression" tabindex="-1">Skills &amp; Progression <a class="header-anchor" href="#skills-progression" aria-label="Permalink to &quot;Skills &amp; Progression&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>An inexperienced character should already be useful.</li><li>Grow through character skill, learned knowledge and player execution.</li><li>Specialization, discovery and reputation offer goals beyond maximizing skills.</li></ul><p><span id="character-progression"></span><span id="useful-from-the-first-day"></span><span id="three-ways-to-grow"></span><span id="a-build-with-tradeoffs"></span><span id="more-than-one-endgame"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Skill</td><td>Improves capability, consistency and the difficulty you can handle.</td></tr><tr><td>Knowledge</td><td>Opens techniques, processes and information worth discovering.</td></tr><tr><td>Player execution</td><td>Makes judgment, positioning and practical understanding matter.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>A shared skill budget encourages character templates.</td><td>Keep a budget, while making supporting and low-investment skills useful alongside specialties.</td></tr><tr><td>Grandmaster skills are a familiar milestone; later eras also offer higher caps.</td><td>The normal target is 100, without an ordinary 120 climb; knowledge can keep growing.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/items/scrolls-of-power/" target="_blank" rel="noreferrer">Official UO: Scrolls of Power</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Two skilled hunters might know different techniques. One becomes known for tracking dangerous prey; another combines hunting with durable field equipment and a trading network.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>The approximate 700-point direction should allow primary specialties, supporting skills and small utility investments. Neither seven maximized skills nor an evenly spread build is intended to be universally best.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/skills.html">Skillcap and teachers</a> · <a href="/Syrolands-Public/en/guide/characters/character-creation.html">Character building</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Professions</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/progression.html">Skills &amp; Progression</a> design specification.</p>',18)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
